import{_ as e,o as a,c as d,a6 as o}from"./chunks/framework.Bd7kzaCy.js";const h=JSON.parse('{"title":"第五部分　跨尺度与跨圈层变换","description":"","frontmatter":{"title":"第五部分　跨尺度与跨圈层变换"},"headers":[],"relativePath":"theory/part-05.md","filePath":"theory/part-05.md"}'),n={name:"theory/part-05.md"};function r(i,t,p,s,c,l){return a(),d("div",null,[...t[0]||(t[0]=[o('<div class="theory-source"><p><a id="part_5"></a></p><h1 id="part-title-5" tabindex="-1">第五部分　跨尺度与跨圈层变换 <a class="header-anchor" href="#part-title-5" aria-label="Permalink to &quot;第五部分　跨尺度与跨圈层变换 {#part-title-5}&quot;">​</a></h1><p>本部分回答：对象、观察或行动从 SP0 变到 SP1 时，哪些内容得到扩展，哪些内容发生收缩，哪些位置不可比较，凭什么建立转换桥，以及什么信息会在转换中丢失。一般过程统称尺度变换；只有九轴积偏序严格成立时，才称尺度升格。</p><h2 id="section-5-1" tabindex="-1">5.1　合同角色与无歧义引用 <a class="header-anchor" href="#section-5-1" aria-label="Permalink to &quot;5.1　合同角色与无歧义引用 {#section-5-1}&quot;">​</a></h2><p>九个尺度轴是 D 类定义，角色为 scale_axis_definition；九个转换算子是 O 类程序，角色为 scale_transformation_operator；U01—U11 是 D 类通用原语定义，角色为 universal_primitive_definition。定义和程序不冒充经验真值，具体跨层因果、对象转换或零结论必须链接预注册 root-instance。</p><p>尺度实体一律使用限定 ID：scale_axis:A 至 scale_axis:J、scale_operator:M01 至 scale_operator:M09、universal_primitive:U01 至 universal_primitive:U11。因此，scale_axis:O 表示组织层级，claim_type=O 表示操作程序，二者不会混淆。依赖只分为 inferential_requires、protocol_requires、specializes 和 applies_to；协议使用 CAUSAL、EVIDENCE、ANALOGY、SOURCE 等正式 ID，不使用中文简称或裸轴名。</p><h2 id="section-5-2" tabindex="-1">5.2　九轴状态与逐轴比较 <a class="header-anchor" href="#section-5-2" aria-label="Permalink to &quot;5.2　九轴状态与逐轴比较 {#section-5-2}&quot;">​</a></h2><p>每个对象和变换绑定：</p><p>SP=&lt;A,X,T,O,C,R,I,N,J&gt;</p><table tabindex="0"><thead><tr><th>轴</th><th>状态字段核心</th><th>expands 的计算见证</th><th>不可替代边界</th></tr></thead><tbody><tr><td>A 聚合层次</td><td>单位、成员集、分区、聚合规则、权重、排除项</td><td>目标总体覆盖源总体，目标分区是源分区的登记粗化</td><td>不得由 O、X、I 或 J 替代</td></tr><tr><td>X 空间范围</td><td>坐标系、空间集合、边界通道、外部连接</td><td>坐标对齐后源空间是真子集</td><td>不得由 A、O、I 或 J 替代</td></tr><tr><td>T 时间跨度</td><td>时间基准、窗口角色、起止点、时滞模型</td><td>同一基准与角色下目标区间真包含源区间</td><td>当前截面和长期路径不能互代</td></tr><tr><td>O 组织层级</td><td>组织图、版本、节点、包含边、接口、重叠</td><td>同版组织 DAG 中目标节点覆盖源节点祖先闭包</td><td>组织上位不等于 J 扩大</td></tr><tr><td>C 因果层次</td><td>因果模型、变量、边、干预语义、抽象映射</td><td>目标模型经语义保持映射覆盖源模型并增加可区分层面</td><td>层级标签、时序和相关不能代替因果桥</td></tr><tr><td>R 观察分辨率</td><td>测量协议、可区分类、参数、误差、保护性省略</td><td>目标协议保留源协议全部区分并至少细分一类</td><td>高分辨率不等于完整或有权行动</td></tr><tr><td>I 影响范围</td><td>结果、阈值、窗口、受影响位置、效应阶次</td><td>对齐后目标受影响位置集真包含源集合</td><td>影响和观察均不等于授权</td></tr><tr><td>N 网络拓扑范围</td><td>图与版本、节点、边、语义、采样边界</td><td>存在语义保持图嵌入且目标覆盖源图</td><td>网络中心不等于责任中心</td></tr><tr><td>J 管辖与授权范围</td><td>原子授权元组集合；每个元组固定来源、主体、单一对象、单一动作、地域、期限、撤回、有效性和证据</td><td>目标有效原子元组规范化集合真包含，且每个新增元组有独立有效性见证</td><td>任何其他轴均不能替代 J；禁止对象集与动作集做笛卡尔积</td></tr></tbody></table><p>每轴关系只有 equal、expands、contracts、incomparable、unknown 五种。比较须保留源与目标状态、使用的规则及版本、实际映射或集合差异、信息损失和不确定性，并使他人能够复核。相同状态不能登记扩展或收缩；contracts 是同轴 expands 的逆关系。非平凡关系的见证必须来自相应领域比较，不能由记录自报“有效”取得。缺少可复核依据时，相关关系保持 unknown。</p><p>“九轴都要登记”不等于“九轴对一切对象都适用”。某轴整体确实不适用时，轴状态使用带理由的 not_applicable 对象，而不是删掉该轴。典型例子是没有行动主体和授权概念的自然过程：其 J 轴不适用，不等于“存在一个空授权集合”。源、目标两端经同一适用性判据均不适用时，该轴可在见证中记为 equal；仅一端不适用而另一端适用时，语义域已经改变，应记 incomparable；材料不足仍记 unknown。这样既保持九轴接口稳定，也不把人类制度语义强塞进广义世界。</p><p>每个轴状态都须满足反身性、反对称性和传递性。为避免“差一点相等”破坏传递，轴状态先按 equality_rule 形成规范化等价类，偏序在这些等价类的商集上定义；容差只能通过预注册的共同规范化器或固定分箱把两端送入同一等价类，不能用任意两点之间“距离小于阈值”直接定义相等。反身性要求规范化状态与自身为 equal；反对称性要求双向不大于只能落入同一等价类；传递性只在中间状态、版本和见证可组合时成立，任何映射、坐标、图版本、变量或授权链断裂都会使关系回到 unknown。</p><p>每轴的主比较量成立还不够。若该轴记录含边界通道、时滞模型、接口、误差模型、干预语义或保护性省略等辅助状态，expands 还要求这些字段存在可组合的语义保持映射；主范围扩大而辅助语义发生无映射冲突时，只能登记 incomparable 或 unknown。这使“范围更大”不会偷渡成“整个轴状态更高”。</p><h2 id="section-5-3" tabindex="-1">5.3　积偏序与变换分类 <a class="header-anchor" href="#section-5-3" aria-label="Permalink to &quot;5.3　积偏序与变换分类 {#section-5-3}&quot;">​</a></h2><p>SP0≼SP1 当且仅当九轴全部为 equal 或 expands；严格关系 SP0≺SP1 还要求至少一轴 expands。机器分类按以下顺序执行：</p><p>任一轴 incomparable：horizontal_or_incomparable；已知不可比不会被另一轴的未知覆盖；</p><p>否则同时出现扩展和收缩：mixed；两种已知方向已经足以排除积偏序，即使还有轴未知；</p><p>否则任一轴 unknown：unresolved；</p><p>九轴全 equal：all_equal；</p><p>仅含 equal/expands 且至少一轴扩展：elevation；</p><p>仅含 equal/contracts 且至少一轴收缩：reduction。</p><p>因此，宏观聚合同时压缩观察分辨率时通常是 mixed，不应笼统叫升格；领域类比常是 horizontal_or_incomparable；材料不足时是 unresolved。只有分类为 elevation 的实例才使用“尺度升格”。观察范围、空间范围、组织范围、影响范围或网络范围扩大，都不会改变 J；J 只能由新的有效授权元组见证扩展。</p><p>J 状态不是“一个来源 + 一组主体 + 一组对象 + 一组动作”的独立字段拼盘，因为那会凭空生成未被授权的对象—动作组合。authorization_tuple_contract 要求每个原子元组只绑定一个来源、一个决策主体、一个对象和一个动作，同时保存地域、有效期、撤回条件、证据和独立复核；多对象或多动作必须拆成多个元组。只有状态为有效的规范化原子元组进入集合比较。J 轴扩展的见证要在 comparison_payload 中列出目标新增而源端没有的完整元组及其独立有效性证据，并与记录的 j_authorization 对齐。任意字符串、tuple ID、自称、实际控制、观察覆盖、影响扩大、上位组织位置或其他轴的扩展都不能使 J 变为 expands。</p><h2 id="section-5-4" tabindex="-1">5.4　算子的结果状态与零结论门 <a class="header-anchor" href="#section-5-4" aria-label="Permalink to &quot;5.4　算子的结果状态与零结论门 {#section-5-4}&quot;">​</a></h2><p>每条原子记录的 operator_ids 必须且只能包含一个算子，selected_operator_branch 再从该算子的分支注册表中唯一选择内部支路，最后用 claim_mode 声明本次评价的模式：descriptive_mapping（描述映射）、root_hypothesis（经验问题族实例）、causal（因果桥）、object_conversion（对象转换）或 intervention_conversion（干预转换）。分支注册表明确每个支路允许哪些模式；三者必须相容并在看结果前冻结，不能因正向门失败切换支路或退回较宽松的描述模式，也不能把一个模式的材料用于救援另一个模式。若一个实际过程包含多个算子，须拆成有序原子记录链：前一步的目标对象与 SP1 对齐后一步的源对象与 SP0，每一步各自登记结果状态、证据、损失和误差。一个总结果不能替多步分别结案。</p><p>算子程序统一使用四个结果状态：</p><p>supported：本次选定分支的桥、决策规则和正向阈值已预注册且通过；只有 G、因果、对象/干预转换分支才强制 root-instance、预选子型和唯一成功判据，纯描述分支可把这些 G 专用字段记为 not_applicable；</p><p>unsupported_or_undecided：桥接不足，或正向门未通过而零结论门也未通过；</p><p>null_supported：只有预注册 null_decision_rule、等价性或充分性检验、功效或灵敏度及容差全部通过时，才支持限定零结论；</p><p>not_evaluated：算子或相应分支尚未运行；已运行且描述桥成立的分支可以是 supported，不能因不需要 G-instance 而降为未评估。</p><p>“未显著”“切断后看似不变”“效应消失”“简单模型表现相当”或“目标证据不足”都不能自动写成 null_supported。这条纪律适用于 M01—M09，而不只适用于跨层因果。</p><h2 id="section-5-5" tabindex="-1">5.5　九种尺度变换算子 <a class="header-anchor" href="#section-5-5" aria-label="Permalink to &quot;5.5　九种尺度变换算子 {#section-5-5}&quot;">​</a></h2><p>每个算子都有独有 semantic_signature，不能复制 M01 的聚合语句冒充其他算子。</p><h3 id="section-5-5-1" tabindex="-1">5.5.1　M01　聚合 <a class="header-anchor" href="#section-5-5-1" aria-label="Permalink to &quot;5.5.1　M01　聚合 {#section-5-5-1}&quot;">​</a></h3><p>签名是“单位—总体分区聚合”。最低桥包括逐单位映射、成员与排除、权重与缺失、替代聚合规则和异质性。信息损失包括尾部、次序、协方差、局部时序及少数位置可见度。总体不能按登记规则复现、合理替代规则造成方向反转，或总体关联被回填为个体属性时，程序失败。即使聚合获得支持，也不得据总体结果直接处置成员。</p><p>聚合的比较首先固定估计对象：地区现住人口的平均改善，与灾前同一批居民的改善，是两种不同问题。迁出、死亡、无法到场和未申请者不能默默变成零需求；需要时并列固定队列、当前截面、进入者和退出者。粗率与标准化率可以同时正确，只有声称它们回答同一问题却发生不一致时，才进一步审查口径、选择或推理错误。〔研究03.04—03.05、22.07、24.01、29.04、31.04〕</p><h3 id="section-5-5-2" tabindex="-1">5.5.2　M02　嵌套 <a class="header-anchor" href="#section-5-5-2" aria-label="Permalink to &quot;5.5.2　M02　嵌套 {#section-5-5-2}&quot;">​</a></h3><p>签名是“边界—成员嵌入”。它必须分成两条支路：</p><p>描述性嵌套只检验边界、成员、重叠、退出和接口映射；它可以成立而没有任何跨层因果。</p><p>跨层因果须有指定通道、相称比较与时间顺序，经验作用按 G2 和 CAUSAL 取证，跨尺度映射另经 D3/E5。只有进一步主张尺度闭合失败、对象或干预转换时，才进入相应 G4 实例；G4 的正向结果不是一切跨层因果成立的必要条件。</p><p>控制当前状态与共同环境后没有条件增量，并不自动证明“没有跨层作用”；只有等价/充分性、功效/灵敏度和容差门同时通过，才可登记限定零结论。描述性嵌套不生成上位优先、下位义务或 J 轴扩展。</p><p>记录时必须在 descriptive_nesting、cross_layer_causal、object_conversion、intervention_conversion 中选一支，并分别绑定描述、因果、对象转换或干预转换模式；不得用描述性嵌套的边界材料支持后面三支。</p><h3 id="section-5-5-3" tabindex="-1">5.5.3　M03　网络传播 <a class="header-anchor" href="#section-5-5-3" aria-label="Permalink to &quot;5.5.3　M03　网络传播 {#section-5-5-3}&quot;">​</a></h3><p>签名是“沿时间化路径传导”。必须登记节点、边、方向、权重、容量、采样边界、候选与替代路径、时延和损耗。连接或同步只生成候选；切断路径后结果不变而零结论门未通过时，仍是 unsupported_or_undecided。网络采样会遗漏弱边、离网位置和跨网桥，只保留终点影响也不能恢复传播次序。中心性不等于意图、责任或处置权限。</p><p>关系强度、桥位、中心性与可动员资源分别观察。四个联系人可能来自四个机构却共用同一消息源；一位熟人也可能提供他人不愿提供的实际转介。网络位置用于寻找通道，通道的容量、成本、替代性和到达时间决定它对指定任务是否真正可用。社会上的多重支持与事实来源的相互独立，不是同一项检验。〔研究26.01—26.02〕</p><h3 id="section-5-5-4" tabindex="-1">5.5.4　M04　时间累积 <a class="header-anchor" href="#section-5-5-4" aria-label="Permalink to &quot;5.5.4　M04　时间累积 {#section-5-5-4}&quot;">​</a></h3><p>签名是“带窗口的纵向组合”。必须冻结时间基准、基线、窗口、时滞、持久阈值和累积/衰减/恢复规则，并比较共同趋势、季节、队列和替代窗口。效应在控制后消失或随窗口变化，只表示正向支持不足；没有通过零结论门，不能发布“无累积”。基础时间组合不预证 G3；只有历史项在控制当前状态后仍提供条件增量时，才链接 G3-instance。</p><h3 id="section-5-5-5" tabindex="-1">5.5.5　M05　制度化 <a class="header-anchor" href="#section-5-5-5" aria-label="Permalink to &quot;5.5.5　M05　制度化 {#section-5-5-5}&quot;">​</a></h3><p>签名是“持久制度写回”。它把五个判断分开：制度事实上存在、法律有效、规范正当、保护是否成立、是否应继续。记录、角色、资源、决策规则或后续转移发生持久改变，可以支持制度化事实；授权无效、参与不足、保护机制失效、缺少申诉/反报复/回滚属于治理失败、规范争议和行动降级理由，不能据此抹掉制度已存在的事实。反过来，制度存在也不证明它合法、正当、具有充分保护或应继续。</p><p>selected_operator_branch 只允许 institutional_fact、institutional_causal_effect、institutional_object_conversion 或 institutional_intervention_conversion。法律有效性审查、治理质量、规范正当性、保护充分性和应否继续没有任何一项能伪装成 institutional_fact 的正向或零结论。</p><h3 id="section-5-5-6" tabindex="-1">5.5.6　M06　涌现 <a class="header-anchor" href="#section-5-5-6" aria-label="Permalink to &quot;5.5.6　M06　涌现 {#section-5-5-6}&quot;">​</a></h3><p>签名是“互动生成目标尺度模式”。源单位、互动规则、目标对象和目标模式须与预登记简单加和模型在同一指标上比较。简单加和模型表现相当，只在充分性/等价、功效/灵敏度和容差门通过时支持“加和已足够”；否则保持未决。宏观模式不能反推唯一微观原因，也不能自动证明下行因果。下行约束须有指定通道、相称因果证据与 D3/E5 映射；涉及尺度闭合或对象、干预转换的附加主张，另按 G4 取证。</p><h3 id="section-5-5-7" tabindex="-1">5.5.7　M07　委托/代表 <a class="header-anchor" href="#section-5-5-7" aria-label="Permalink to &quot;5.5.7　M07　委托/代表 {#section-5-5-7}&quot;">​</a></h3><p>签名是“代表事实分类与可选授权转移”。必须分开记录：代表性主张、实际代行事实、争议或自任代表、有效委托、J 轴权限转移。无授权时仍可记录实际代行及其影响和责任，但不得登记 J 扩展；授权无效会触发停止或降级，却不能把已经发生的代行与后果删除。多数、可见性、影响力、自称或实际控制都不等于有效委托。</p><p>记录必须在 representation_claim、actual_acts、delegation_validity、J_transfer 中选一支。前三支即使获得支持也不能改变 J；只有 J_transfer 与结构化授权元组、独立有效性证据和 j_authorization 同时通过时，J 才可扩展。</p><h3 id="section-5-5-8" tabindex="-1">5.5.8　M08　压缩/抽象 <a class="header-anchor" href="#section-5-5-8" aria-label="Permalink to &quot;5.5.8　M08　压缩/抽象 {#section-5-5-8}&quot;">​</a></h3><p>签名是“多对一表示压缩”。源材料、算法、阈值、版本、误差、不可恢复信息和任务所需不变量必须可追踪。unknown、not_applicable、not_observable、withheld_for_protection 必须保持区分，任何一种都不能压成“不存在”。对拟议高影响行动存在重大任务相关损失的表示，不得用于支持该行动。</p><p>可用一个精确的任务充分性条件说明压缩：源状态为x，表示为z=f(x)，当前所需答案为q(x)。当且仅当任意f(x₁)=f(x₂)都意味着q(x₁)=q(x₂)，才存在函数g使q=g∘f。它说明原状态未必能恢复，而当前问题仍可能准确回答；它没有保证g易于计算，也没有保证换一个问题、环境或干预后仍充分。〔研究05.01—05.02、05.05—05.06；此处为形式说明〕</p><p>对有限非空状态域和实数目标 q，若解码器可以输出任意实数，并以全域最坏绝对误差为损失，表示的最小恢复误差恰为最大原像内目标振幅的一半。令每个非空原像中的最小、最大目标值为a_z、b_z，则最优误差为 (1/2)max_z(b_z−a_z)，逐原像输出中点即可达到。给定容差ε，存在误差不超过ε的解码器，当且仅当各原像振幅都不超过2ε。换成向量、整数输出、平均损失或未知分布时，不能直接沿用此式。</p><p>连续转换须保持同一最终查询。设 f:X→Z、h:Z→W，第一段对最终目标q充分，q=g∘f；最终表示h∘f仍充分，当且仅当g在h限制到实际像集f(X)的每个原像上常值。无须约束不可能到达的中间值，也不能用第二段完成另一个局部任务，替原最终查询结案。该条件及其证明见附录C.6—C.7。</p><h3 id="section-5-5-9" tabindex="-1">5.5.9　M09　横向迁移 <a class="header-anchor" href="#section-5-5-9" aria-label="Permalink to &quot;5.5.9　M09　横向迁移 {#section-5-5-9}&quot;">​</a></h3><p>签名是“跨领域类比迁移”。必须登记映射、差异、断裂、禁止映射、目标责任链和 J 轴差异。源域材料只生成目标候选；supported 或 null_supported 都必须来自独立目标实例。目标证据不足是 not_evaluated 或 unsupported_or_undecided，不是目标机制不存在的证明。类比不生成目标领域行动授权。</p><h2 id="section-5-6" tabindex="-1">5.6　通用原语的尺度边界 <a class="header-anchor" href="#section-5-6" aria-label="Permalink to &quot;5.6　通用原语的尺度边界 {#section-5-6}&quot;">​</a></h2><p>通用原语是 D 类接口，不再携带经验零模型或证伪模板。尤其需要锁住四项边界：</p><p>U07 的基础反馈只要求返回通道和后续状态更新，不要求 G3。反馈介导学习还须有更新载体、跨轮保留、实际调用和任务结果的相应证据；只有主张当前注册状态之外的历史条件增量时，才追加 G3（参见§4.5、§6.3）。</p><p>U09 的瞬时需求—容量缺口不要求 G3；累积损伤或迟恢复须另核当前损伤或容量载体、形成过程与后续恢复。只有追加当前表示之外的历史增量主张，才进入 G3。</p><p>U10 只登记候选痕迹、载体和保留窗口，不预证路径依赖；G3 仍须证明历史项在控制当前状态后的条件增量。</p><p>U11 的基础相位模式不要求 G3 或 G4；因果触发另检 G2，当前载体维持的持续或迟恢复按§4.5取证，当前表示之外的历史增量型迟滞另检 G3，对象转换另检 G4。</p><p>同理，U01 只登记候选对象而不预保证 G1；U05 的关系定义不证明因果；U06 的通道字段不证明通道效应。</p><h2 id="section-5-7" tabindex="-1">5.7　统一尺度变换记录 <a class="header-anchor" href="#section-5-7" aria-label="Permalink to &quot;5.7　统一尺度变换记录 {#section-5-7}&quot;">​</a></h2><p>每个实例都必须出现十四节和全部字段：</p><table tabindex="0"><thead><tr><th>节</th><th>必填字段</th></tr></thead><tbody><tr><td>identity</td><td>contract_id、concept_id、version、proposition_ids、purpose</td></tr><tr><td>scale</td><td>SP0、SP1、九条 axis_differences、unchanged_axes、transformation_class、j_authorization</td></tr><tr><td>objects</td><td>源/目标有效对象、source_K、target_K、identity_mapping、单位、总体、边界、成员、排除项</td></tr><tr><td>semantics</td><td>preserved_core、allowed_changes、lost_elements、prohibited_mappings</td></tr><tr><td>transformation</td><td>单一算子、selected_operator_branch、claim_mode、规则、因果桥、时滞、映射误差、有效期、root-instance、子型、成功判据、正向和零决策规则、正向阈值、等价/充分性检验、功效/灵敏度、容差、结果状态</td></tr><tr><td>variables</td><td>输入、状态、输出和跨变量依赖</td></tr><tr><td>evidence</td><td>源/目标证据、覆盖、异质性、反例、缺席信号、替代解释、残差检验、复制或外部验证</td></tr><tr><td>loss</td><td>压缩细节、不可恢复信息、低可见位置和局部排除区</td></tr><tr><td>responsibility</td><td>行动者、决策者、授权者、承接载体、责任主体、受益者和成本承担者</td></tr><tr><td>normative</td><td>价值前提、选择类型、规范选择记录、运行时 N 原则、授权来源、C12 门和 O1-O4 程序</td></tr><tr><td>protection</td><td>保护适用性、低权力位置、安全提交和反报复</td></tr><tr><td>action</td><td>判断上限、行动上限、禁止动作、停止条件、责任人和机器可指向的 selected_action</td></tr><tr><td>correction</td><td>申诉、复核、回滚、修复和写回</td></tr><tr><td>lifecycle</td><td>有效期、复审点、暂停和退场</td></tr></tbody></table><p>source_K、target_K 和 identity_mapping 共同决定对象保持、转换或不可比；同名不是同一性证据。映射记录必须同时保存源、目标 K 的摘要，源对象与目标对象分别在两套 K 下的四项判据结果，正向与反向映射，保持和违反的判据，结果前冻结的预注册引用，以及可复核的验证制品与哈希。判据结果只允许 passed、failed 或 undetermined，不能用一个布尔值掩盖是哪一项没有通过。</p><table tabindex="0"><thead><tr><th>K 映射分类</th><th>最低成立条件</th><th>结果上限</th></tr></thead><tbody><tr><td>same_object</td><td>双向映射均有效；源对象与目标对象在 source_K、target_K 下四项检查均通过；保持判据非空且违反判据为空</td><td>可在当前合同内沿用对象身份，但不推出语义、因果或规范性质也保持</td></tr><tr><td>converted_object</td><td>source_under_source_K 与 target_under_target_K 通过，target_under_source_K 失败；违反项和结果前预注册引用具体；另有 object_conversion 模式及取得支持的 G4b 实例</td><td>只登记预注册 K 下的对象转换，不得在结果后改写 K 制造转换</td></tr><tr><td>incomparable</td><td>两端各自在本方 K 下通过，至少一个交叉 K 检查失败；正反向映射保存完整尝试记录且至少一项验证为无效，并有可解析证据</td><td>表示已知不可比，只能 unsupported_or_undecided；不是“尚未评估”</td></tr><tr><td>undetermined</td><td>必要映射、判据或证据尚不足以完成分类；四项判据分别保留已知的 passed、failed 与尚未确定的 undetermined，并指出哪一项阻断整体判断</td><td>只能 unsupported_or_undecided 或 not_evaluated；不把部分已知清空，也不据整体未决推定不可比或对象转换</td></tr></tbody></table><p>对象同一性必须允许独立复算或复核。相同对象与相同判据可直接核对；非平凡保持或转换须保留两端对象、两套 K、映射方向、四项判据结果及支持材料。一个名称、编号、自报有效状态或散列值都不能代替这种语义核验。</p><p>对象转换模式与结果四态必须一致：supported 才对应 converted_object；null_supported 对应通过零结论三门的 same_object；unsupported_or_undecided 只允许保持、已知不可比或未决；对象转换尚未运行时，整体分类保持 undetermined，已独立核得的局部判据仍保留。因此，未检验和检验失败都不能先把目标写成“已经转换”。其他 claim_mode 也不得在同一条原子记录里兼报 converted_object，对象转换必须拆成自己的原子检验。</p><p>claim_mode 为 root_hypothesis、causal、object_conversion 或 intervention_conversion 时必须填写 root_instance_ids，后三者还必须给出非空因果桥；只有 descriptive_mapping 可把 root-instance、子型和成功判据标为 not_applicable。非描述模式登记 supported 或 null_supported 时，还必须向验证器提交可解析的 root-instance 注册表，并核对实例 ID、根族、合同版本、预选子型、唯一成功判据与实例状态；一个看似正确的字符串前缀不能充当实例。描述桥正向门通过时可以记 supported，只有所选模式没有运行时才记 not_evaluated。</p><p>十四节是稳定接口，不是把人类治理语义投射给所有对象。protection.applicability 必须显式登记对象类型、下游用途、理由和证据引用，不能从 actors 等空列表反推。对象类型为 nonhuman，且用途只含 description_only 或有证据证明不影响人类/有感主体的 nonhuman_intervention_without_human_or_sentient_effect 时，safe_submission 与 anti_retaliation 可带理由记 not_applicable；但现实实验或工程干预仍有行动主体和对象，必须填写具体 J、行动责任人、停止、复核与回滚，只有纯描述用途才允许 J 不适用。自然系统中的能量、物质或计算资源本身不触发这套人类保护合同。对象为人类、有感非人、混合或未知，或用途涉及人的评价、其稀缺资源配置、权利、暴露风险或现实处置时，保护字段立即成为强制项，不得沿用先前的不适用状态。保护不适用绝不推出行动正当，规范选择仍另行判断。</p><p>action_owner 只说明谁负责执行或停止，不能反推 claim_mode=intervention_conversion，也不能证明行动有效或正当。任何外部行动必须链接 selection_record_id，公开 value_premises 与运行时 normative_principle_ids；N1 单独只能阻止越权，不能产生正向方案。选择记录中的 feasible_alternatives 不是名称列表，而是带稳定 option_id 的结构化方案；每项冻结 option_kind、动作类型、目标对象、地域、有效期、可逆性、预期影响和分配影响，并且恰有一项 option_kind=no_action，由 no_action_option_id 唯一指向。selected_action.selected_option_id 必须解析到一项 external_action，而且其动作、对象、地域和有效期与该方案逐项相等；选择不行动 ID、只对上自然语言标签，或同时改写动作与 J 而不改获准方案，都必须被拒绝。至少一条当前有效且独立复核的 J 原子授权元组还必须同时覆盖该主体、对象、动作、地域和期限，并与授权来源一致；一条无关但形式有效的授权不能为拟议行动背书。记录还必须有通过的十组件 c12_gate、O1-O4 procedure_ids、行动责任人、禁止动作、停止、保护、申诉、复核和回滚。缺任一项时，行动上限只能是不行动或继续审议；经验上的干预转换另由相应 root-instance 判断。</p><p>记录链只提供组合次序，不把前一步的支持自动传递给后一步。链校验必须保证每步 contract_id 唯一、每步只有一个算子、相邻对象引用及同一性判据兼容、前一 SP1 与后一 SP0 一致；任一步未决、失效或损失超限，都要在链级输出中保留，不能被最终一步的成功覆盖。</p><p>链级评价还要明确最终任务是否与逐步任务一致，以及共享资源是否被重复承诺。两项任务可以分别在一单位容量下可行，却在同一期共用这一单位时不可联合完成；期限、资源或允许策略合法改变后，应评价新的联合方案。表示充分性、联合因果响应与联合资源可行性各有判据，不能用其中一项通过代替其余两项。</p><h2 id="section-5-8" tabindex="-1">5.8　机器校验与保护底板 <a class="header-anchor" href="#section-5-8" aria-label="Permalink to &quot;5.8　机器校验与保护底板 {#section-5-8}&quot;">​</a></h2><p>机器校验负责检查字段、引用、版本和结果状态的一致性，以及已有逐轴关系是否被正确组合。它不替代领域比较器对几何、组织图、因果抽象、网络嵌入、对象同一性或授权有效性的判断。实质比较和独立对象材料缺失时，不能凭完整记录或算法输出登记尺度升格。实现采用何种模式或注册表，须能承担同样的可追溯与复核责任。</p><p>四种缺失状态构成封闭词表：unknown 表示当前未知，not_applicable 表示按合同确实不适用，not_observable 表示当前通道和窗口不可观察，withheld_for_protection 表示为保护而不公开。四者都不是“不存在”，也不能删除字段代替状态。</p><p>carrying_vehicles 与 responsible_subjects 必须分栏；承接、可见、受影响或能力较强都不自动产生责任。凡对人类或有感主体的权利、稀缺资源配置、暴露风险或现实处置产生影响，保护底板必须识别低权力位置和局部排除区，提供安全提交、反报复、停止、申诉、复核和回滚，且不得记为不适用。保护不足时，判断上限与行动上限同时降低。纯描述记录的条件性不适用也不能被下游行动继承；用途改变时必须重开保护审查。</p><h2 id="section-5-9" tabindex="-1">5.9　证据边界与独立支持 <a class="header-anchor" href="#section-5-9" aria-label="Permalink to &quot;5.9　证据边界与独立支持 {#section-5-9}&quot;">​</a></h2><p>M01—M09 的名称、编号、语义签名和分类结果只规定变换应怎样描述与检验，不构成变换已经发生、映射有效或目标性质成立的经验支持。内部概念标签、示例、字段完整度和算法自报结果均不得进入 source_evidence 或 target_evidence 代替对象材料。</p><p>每个实际变换必须分别在源对象和目标对象上取得可解析的独立材料，明确映射、保持项、改变项、丢失项、误差与竞争解释，并接受同一结果状态、正向门和零结论门。源域材料只能生成目标候选；目标侧没有独立支持时，结论停在待检验映射或未知。</p><h2 id="section-5-10" tabindex="-1">5.10　跨圈层关系变换 <a class="header-anchor" href="#section-5-10" aria-label="Permalink to &quot;5.10　跨圈层关系变换 {#section-5-10}&quot;">​</a></h2><p>尺度变换与圈层关系变换必须分开。尺度变换回答同一问题在 SP0 与 SP1 之间哪些变量保持、改变或丢失；圈层关系变换回答两个或多个候选圈层在同一或不同尺度上如何并列、包含、重叠、桥接、竞争或临时形成。一个关系变化可能伴随尺度变化，但不能用其中一个词替代另一个合同。</p><p>跨圈层记录至少包含关系源、关系目标、静态关系类型、成员或接口基准、方向、通道、时延、阈值、时间窗、证据、反例和前后快照。transformed 只作为关系更新结果：原平行关系可能因桥接者出现而转为桥接，重叠关系可能因制度整合转为嵌套，临时圈层可能制度化或解体。每次转化都要检查 K 是否保持；K 失效时记录对象转换，不以改名延续旧对象。</p><table tabindex="0"><thead><tr><th>变换问题</th><th>需要调用</th><th>不得偷换</th></tr></thead><tbody><tr><td>个体状态能否代表团队</td><td>聚合 M01、尺度合同与分布损失</td><td>成员属于团队不等于代表团队</td></tr><tr><td>团队是否被组织包含</td><td>嵌套 M02 与具体包含基准</td><td>共同上级不等于成员包含</td></tr><tr><td>两圈层是否因共享成员相关</td><td>重叠关系、成员映射与共同环境</td><td>重叠不自动产生有效反馈</td></tr><tr><td>桥接者是否改变另一圈层</td><td>M03 传播、通道和反事实</td><td>接触不等于传导，传导不等于代表</td></tr><tr><td>临时群体是否形成持久对象</td><td>K、纵向对象材料与 M05；主张分组增益另检 G1，主张历史条件残差另检 G3</td><td>留痕不等于制度化，持久事实不必依赖额外历史残差</td></tr></tbody></table><p>多重成员关系要求同一行动者在多个圈层中保留不同角色、可见信息、责任、风险和退出能力。不得先把行动者聚合为单一状态，再把该状态复制到所有圈层。跨圈层推演应从局部状态出发，经已声明的成员或接口通道传播，并逐步登记聚合损失。</p><p>翻译有任务，也有权限。正确转述某人的话、帮助双方互相理解、获准发表原话、代表该人签署协议，是四种不同能力或资格。同一译法能完成预约，却可能不足以保存诗歌节奏或法律身份差别；对后一任务的不足，不能倒写前一任务从未完成。应保留能成功的有限转译，同时明确未被转移的意义和权利。〔研究12.10、26.08—26.09〕</p><h3 id="section-5-10-1" tabindex="-1">5.10.1　三类变换必须分开 <a class="header-anchor" href="#section-5-10-1" aria-label="Permalink to &quot;5.10.1　三类变换必须分开 {#section-5-10-1}&quot;">​</a></h3><p>尺度变换回答同一问题在两个尺度剖面之间哪些变量保持、改变或丢失；圈层关系变换回答候选圈层之间的并列、包含、重叠、桥接、竞争或临时关系如何更新；表示或表述转义回答一个有来源的载荷怎样进入目标任务的词汇、变量或表达。三者可以同时发生，但必须拆成有序记录。</p><p>转义是一类独立说明保持、改变与损失的运行合同。它可以调用传播、压缩、横向迁移或其他算子；合同之间按各自输入、输出、判据和失败条件连接，不能仅凭命名差异增加算子，也不能把多个不同操作的失败并成一个总状态。</p><h3 id="section-5-10-2" tabindex="-1">5.10.2　转义损失审计 <a class="header-anchor" href="#section-5-10-2" aria-label="Permalink to &quot;5.10.2　转义损失审计 {#section-5-10-2}&quot;">​</a></h3><p>若两个在源任务中可区分的源状态，在目标表示中无法区分，则针对该项区别登记任务相关损失。恒等映射、可逆编码或对目标任务充分的映射可能没有检测到相关损失，因此规则是“不得预设无损”，而不是“必然有损”。</p><table tabindex="0"><thead><tr><th>审计项</th><th>最低问题</th><th>不得偷换</th></tr></thead><tbody><tr><td>保持</td><td>哪些事实、关系、模态、权利或不确定性必须不变</td><td>保持标题不等于保持语义</td></tr><tr><td>改变</td><td>哪些格式、单位、粒度或表达允许变化</td><td>允许改变不等于任意改义</td></tr><tr><td>折叠</td><td>哪些源差异在目标端合并</td><td>折叠不等于源差异不存在</td></tr><tr><td>遗漏</td><td>哪些内容未进入目标表示及原因</td><td>保护性不公开不等于不存在</td></tr><tr><td>新增</td><td>哪些解释、推断或目标变量由转换产生</td><td>新增变量不等于发现现实实体</td></tr><tr><td>回返</td><td>异常出现时回到哪个父记录或合同</td><td>回返只重开审查，不修补旧运行</td></tr></tbody></table><p>往返重构可以作为检验，但不是充分条件。一个转换可能借助隐藏源记录实现表面往返，却没有保持目标任务语义；另一个单向摘要可能对指定任务充分。复核必须回到预先声明的保持项、损失容限和目标侧结果。</p><p>目标表示是否保留所需区别，与实际规则是否正确使用该区别，是两项判断。处置错误不能单独证明转义损失；差异仍可辨而使用错误时，把缺口登记在规则或执行环节。表示损失与执行错误也可能并存，应分别说明依据，并保留其他已经成立的局部结果。</p><p>两类失败并存时，不应把同一不可避免误差重复计为额外规则故障。在某个原像中，若目标答案本来就不唯一，任何仅使用当前表示的确定规则都不可能对全部源状态答对；这本身证明表示不足。若另一个非空原像的目标答案已经唯一，实际规则却给出错误答案，则该处提供独立规则错误的充分见证。现实内部表示未知时，公开原件仍可查阅不证明执行者当时已经拥有该区别；资料存在、及时访问和实际使用要分别核对。</p><h3 id="section-5-10-3" tabindex="-1">5.10.3　有效变量、闭合与残差回返 <a class="header-anchor" href="#section-5-10-3" aria-label="Permalink to &quot;5.10.3　有效变量、闭合与残差回返 {#section-5-10-3}&quot;">​</a></h3><p>有效变量是目标尺度或目标任务中，为压缩状态并改善预定解释、前瞻或方案比较而提出的变量候选。它必须绑定对象、尺度、时间窗、任务、测量、简单基线、误差、失效与退役；有效不等于真实实体、根因、普遍变量或授权依据。</p><p>目标表示不默认动力闭合。静态描述或同尺度查询先核对来源、转换规则与任务答案，必要时使用F1及F4；形式动力模型依F2核对闭合，现实映射另取证。描述映射不适用的G专用字段可以注明理由后记为not_applicable。只有以§4.6申请尺度闭合、对象或干预转换的正式经验支持时，才进入相应G4实例的正向门与零结论门；不能为了满足格式而虚构尺度变化。未达到显著增量不能自动证明闭合；出现增量时，把相应影响登记为记忆、噪声、迟滞、未解析项或残差候选，不能按形状直接命名新实体。</p><p>统一尺度变换记录须在用途与语义字段中注明目标任务，在转换、证据和损失字段中记录父表示、折叠差异、回返位置、重构检验和目标有效变量候选。缺少有关信息时保留明确缺失状态；不得由一个表格完整推定源语义已经全部保留。</p><h2 id="section-5-11" tabindex="-1">5.11　平行与嵌套的同时表示 <a class="header-anchor" href="#section-5-11" aria-label="Permalink to &quot;5.11　平行与嵌套的同时表示 {#section-5-11}&quot;">​</a></h2><p>现实结构不是单棵层级树。局部包含关系可以与横向网络、成员重叠、竞争资源和平台桥接同时存在。表示层采用有向多重关系图：节点维持各自对象合同，边维持各自关系合同；“上层”只表示某项包含、管辖或聚合关系，不表示更真实、更正确或更有权。</p><p>当多个圈层共享环境却没有直接通道时，模型保留共同条件节点，不虚构圈层间直接边；当通道只在事件窗口内开放时，边具有起止时间；当不同关系方向相反时，分别建边。这样才能在事件发生后判断哪条关系真正改变，而不是把整个结构一次性重画成事后故事。</p></div>',1)])])}const u=e(n,[["render",r]]);export{h as __pageData,u as default};
